package main
import ("log";"net/http";"os")
func main(){p:=os.Getenv("PORT");if p==""{p="10000"};http.HandleFunc("/",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/html; charset=utf-8");w.Write([]byte(html))});log.Println(p);http.ListenAndServe(":"+p,nil)}
const html=
"<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><div><select id=m><option value=11>Nov<option value=12>Des</select><input id=y value=2026><button onclick=R()>Sawa</button><div style='display:flex'><div style='flex:1;background:#2e7d32;color:#fff'>MAPATO<br><span id=a>0</span></div><div style='flex:1;background:#c00;color:#fff'>MATUMIZI<br><span id=b>0</span></div><div style='flex:1;background:#1565c0;color:#fff'>SALIO<br><span id=c>0</span></div></div><div><b>Wanachama <button onclick=W()>+ Mpya</button></b><div id=wl></div></div><div><select id=sw></select><select id=sa><option value=hisa>Hisa<option value=ada>Ada<option value=marejesho>Marejesho<option value=michango>Mch<option value=mkopo_toka>Mkopo</select><input id=kv><button onclick=M()>Hifadhi</button></div><div><button onclick=E()>Pakua Excel</button><div id=hi style='font-size:12px'></div></div></div><script>D=JSON.parse(localStorage.v8||'null')||{w:[],m:[]};function S(){localStorage.v8=JSON.stringify(D);R()}function W(){j=prompt('Jina:');if(j){D.w.push({j:j});S()}}function M(){w=(sw.value||'').trim();a=sa.value;k=+kv.value;if(!w||!k)return alert('Jaza');D.m.push({w:w,a:a,k:k,mm:+m.value,yy:+y.value});if(a=='mkopo_toka'){f=Math.round(k*0.05);D.m.push({w:w,a:'fomu',k:f,mm:+m.value,yy:+y.value})}kv.value='';S()}function R(){mm=+m.value;yy=+y.value;mi=D.m.filter(x=>x.mm==mm&&x.yy==yy);mp=0;mt=0;mi.forEach(t=>{if(['hisa','ada','marejesho','fomu','michango'].includes(t.a))mp+=t.k;if(t.a=='mkopo_toka')mt+=t.k});a.innerText=mp;b.innerText=mt;c.innerText=mp-mt;wl.innerHTML=sw.innerHTML='';if(!D.w.length)wl.innerHTML='Hakuna';D.w.forEach((x,i)=>{wl.innerHTML+=x.j+' <button onclick=\"D.w.splice('+i+',1);S()\">X</button><br>';sw.innerHTML+='<option>'+x.j+'</option>'});hi.innerHTML='';mi.slice().reverse().forEach((t,idx)=>{let i=D.m.length-1-idx;hi.innerHTML+=t.w+'-'+t.a+'-'+t.k+' <button onclick=\"Ed('+i+')\">E</button> <button onclick=\"D.m.splice('+i+',1);S()\">X</button><br>'})}function Ed(i){t=D.m[i];v=prompt('Kiasi:',t.k);if(v&&+v>0){t.k=+v;S()}}function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;')}function Rr(r){s='<Row>';r.forEach(v=>{s+='<Cell><Data ss:Type=\"String\">'+esc(v)+'</Data></Cell>'});return s+'</Row>'}function E(){try{all=D.m.filter(x=>x.mm==+m.value&&x.yy==+y.value);if(!all.length)return alert('Hakuna');r1=[['Jina','Ada']];r2=[['Jina','Mkopo','Fomu','Rejesho','Baki']];r3=[['Jina','Hisa']];r4=[['Jina','Mch']];am={};dm={};hm={};mc={};all.forEach(t=>{let w=(t.w||'').trim();if(!am[w]){am[w]=0;hm[w]=0;mc[w]=0}if(!dm[w])dm[w]={c:0,f:0,r:0};if(t.a=='ada')am[w]+=t.k;if(t.a=='mkopo_toka')dm[w].c+=t.k;if(t.a=='fomu')dm[w].f+=t.k;if(t.a=='marejesho')dm[w].r+=t.k;if(t.a=='hisa')hm[w]+=t.k;if(t.a=='michango')mc[w]+=t.k});for(j in am)r1.push([j,am[j]]);for(j in dm){d=dm[j];if(d.c>0||d.r>0||d.f>0)r2.push([j,d.c,d.f,d.r,d.c-d.r])}for(j in hm)r3.push([j,hm[j]]);for(j in mc)if(mc[j])r4.push([j,mc[j]]);if(r3.length==1)r3.push(['-',0]);if(r4.length==1)r4.push(['-',0]);function Sh(n,r){h='<Worksheet ss:Name=\"'+n+'\"><Table>';r.forEach(x=>{h+=Rr(x)});return h+'</Table></Worksheet>'}xml='<?xml version=\"1.0\"?><Workbook xmlns=\"urn:schemas-microsoft-com:office:spreadsheet\" xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\">'+Sh('Ada',r1)+Sh('Mikopo',r2)+Sh('Hisa',r3)+Sh('Mch',r4)+'</Workbook>';b=new Blob([xml],{type:'application/vnd.ms-excel'});u=URL.createObjectURL(b);x=document.createElement('a');x.href=u;x.download='U.xls';document.body.appendChild(x);x.click();setTimeout(()=>{document.body.removeChild(x);URL.revokeObjectURL(u)},0)}catch(e){alert('Excel error:'+e.message)}}m.value=11;R();</script>"
